?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PDF to JPG — SmartToolz</title><script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js"></script><style>*{box-sizing:border-box}body{margin:0;background:#f6f8fc;color:#172033;font-family:Inter,system-ui,Arial,sans-serif}.page{width:min(1200px,calc(100% - 28px));margin:32px auto 70px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:20px}.card{background:#fff;border:1px solid #e5e9f0;border-radius:20px;padding:26px;box-shadow:0 14px 40px #18213b0c}.hero{margin-bottom:18px}.hero h1{font-size:clamp(30px,5vw,46px);margin:0 0 8px}.muted{color:#707b8e;line-height:1.6}.drop{border:2px dashed #d6dbea;border-radius:16px;padding:45px 20px;text-align:center;cursor:pointer;margin:20px 0}.drop.drag{border-color:#635bff;background:#f7f6ff}.btn{border:0;border-radius:11px;padding:12px 17px;background:#635bff;color:#fff;font-weight:800;cursor:pointer}.btn:disabled{opacity:.5}.progress{height:9px;background:#edf0f5;border-radius:9px;margin:18px 0;overflow:hidden}.bar{height:100%;width:0;background:#635bff;transition:width .2s}.result{margin-top:15px;padding:13px;border-radius:12px;background:#f7f8fb;border:1px solid #e5e9f0}.tools{position:sticky;top:90px;max-height:calc(100vh - 110px);overflow:auto}.tools h3{margin-top:0}.tools a{display:block;padding:9px 10px;margin:3px 0;border-radius:9px;text-decoration:none;color:#536075;font-size:13px;font-weight:700}.tools a:hover{background:#f0efff;color:#635bff}@media(max-width:800px){.layout{grid-template-columns:1fr}.tools{position:static;max-height:none}}</style></head><body>
<?php require_once dirname(__DIR__) . '/header.php'; ?><?php require_once __DIR__.'/../header.php';?><main class="page"><section class="card hero"><h1>PDF to JPG</h1><p class="muted">Convert PDF pages into JPG images directly in your browser.</p></section><div class="layout"><section class="card"><input id="file" type="file" accept="application/pdf" hidden><div id="drop" class="drop"><strong>📄 Drop your PDF here</strong><br><span class="muted">or click to choose a PDF</span></div><button id="convert" class="btn" disabled>Convert to JPG</button><div class="progress"><div id="bar" class="bar"></div></div><div id="result" class="result">No PDF selected.</div></section><aside class="card tools"><h3>All Tools</h3><a href="/smart-toolz/tools/image-compressor.php">Image Compressor</a><a href="/smart-toolz/tools/png-to-jpg.php">PNG to JPG</a><a href="/smart-toolz/tools/jpg-to-webp.php">JPG to WebP</a><a href="/smart-toolz/tools/png-to-webp.php">PNG to WebP</a><a href="/smart-toolz/tools/gif-maker.php">GIF Maker</a><a href="/smart-toolz/tools/pdf-merger.php">PDF Merger</a><a href="/smart-toolz/tools/pdf-splitter.php">PDF Splitter</a><a href="/smart-toolz/tools/pdf-compressor.php">PDF Compressor</a><a href="/smart-toolz/tools/pdf-to-png.php">PDF to PNG</a><a href="/smart-toolz/tools/qr-generator.php">QR Generator</a><a href="/smart-toolz/tools/age-calculator.php">Age Calculator</a><a href="/smart-toolz/tools/json-formatter.php">JSON Formatter</a><a href="/smart-toolz/tool.php">View All Tools →</a></aside></div></main><?php require_once __DIR__.'/../footer.php';?><script>const file=document.getElementById('file'),drop=document.getElementById('drop'),btn=document.getElementById('convert'),result=document.getElementById('result'),bar=document.getElementById('bar');let selected=null;drop.onclick=()=>file.click();file.onchange=()=>pick(file.files[0]);['dragenter','dragover'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.remove('drag')}));drop.ondrop=e=>pick(e.dataTransfer.files[0]);function pick(f){if(!f)return;if(f.type!=='application/pdf'){result.textContent='Please choose a PDF file.';return}selected=f;btn.disabled=false;result.textContent=f.name+' selected.'}btn.onclick=async()=>{if(!selected)return;btn.disabled=true;bar.style.width='0%';result.textContent='Reading PDF…';try{const pdf=await pdfjsLib.getDocument({data:await selected.arrayBuffer()}).promise;for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i),v=p.getViewport({scale:1.7}),c=document.createElement('canvas');c.width=Math.ceil(v.width);c.height=Math.ceil(v.height);await p.render({canvasContext:c.getContext('2d',{willReadFrequently:true}),viewport:v}).promise;await new Promise(resolve=>c.toBlob(b=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='page-'+i+'.jpg';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);resolve()},'image/jpeg',.9));bar.style.width=Math.round(i/pdf.numPages*100)+'%'}result.textContent=pdf.numPages+' page(s) converted.'}catch(e){console.error(e);result.textContent='Could not convert this PDF. Please try another file.'}finally{btn.disabled=false}};</script>
